#!/usr/bin/env python3
# patch-158-G8: fix appointment screen centering
"""
The multi-asset view's outer wrapper had max-width: 1400px and
margin: 0 auto, which centered the page content. No other tenant
view does this — customers/show, inventory/index, even the legacy
appointments/show all start @section('content') with no wrapper,
letting the tenant layout handle width.

Result: this one page looked center-aligned while everything else
filled the content area. Fixed by dropping the two style props.

Single-line CSS change, single-file view patch.
"""
